default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('AllowRspndrOnDomain', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD [AllowRspndrOnDomain]'
    $mismatchCount++
}

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('AllowRspndrOnPublicNet', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD [AllowRspndrOnPublicNet]'
    $mismatchCount++
}

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('EnableRspndr', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD [EnableRspndr]'
    $mismatchCount++
}

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('ProhibitRspndrOnPrivateNet', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]0)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD [ProhibitRspndrOnPrivateNet]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -Name 'AllowRspndrOnDomain' -Value 0 -PropertyType DWord -Force | Out-Null
if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -Name 'AllowRspndrOnPublicNet' -Value 0 -PropertyType DWord -Force | Out-Null
if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -Name 'EnableRspndr' -Value 0 -PropertyType DWord -Force | Out-Null
if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\LLTD' -Name 'ProhibitRspndrOnPrivateNet' -Value 0 -PropertyType DWord -Force | Out-Null
exit 0
